INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(1,'Proxy DNS Records through Cloudflare','Ensure all relevant DNS records (A, AAAA, CNAME) pointing to your origin are proxied (orange-clouded) through Cloudflare to hide origin IPs and apply security and performance features.','General',1,1,'Mandatory','High','Easy','Cloudflare must manage the DNS records',NULL,'https://developers.cloudflare.com/dns/proxy-status/','Proxying is required for Cloudflare application services (WAF, rate limiting, bot protection, caching) to apply. Avoid DNS-only (grey-clouded) records unless needed for non-HTTP use cases: they expose the origin IP address.','2025-04-22 08:24:32','2026-10-03 23:29:12');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(2,'Enable DNSSEC','Enable Domain Name System Security Extensions to ensure DNS responses are authentic.','Security',1,1,'Recommended','High','Easy','It is recommended to have Cloudflare be the Authoritative DNS provider',NULL,'https://developers.cloudflare.com/dns/dnssec/','Assumes Cloudflare is the authoritative DNS provider.','2025-04-22 08:24:32','2025-04-22 08:24:32');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(3,'Test Rules with Plan-Appropriate Observation','Observe the expected matches before enforcing a WAF custom rule or rate limiting rule. Use Log where available, then deploy a narrowly scoped mitigation and monitor Security Events.','General',4,2,'Recommended','Medium','Easy','Log for custom rules and rate limiting rules requires Enterprise. Other fields, periods, actions, and quotas depend on the plan and contract.',NULL,'https://developers.cloudflare.com/waf/custom-rules/create-dashboard/','Dry run validates configuration, not traffic matches. Without Log, estimate matches with analytics, use conservative thresholds, and test one host/path first. Managed Challenge is appropriate only for interactive browser traffic; APIs need non-interactive controls. Security Events may be sampled.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(4,'Deploy WAF Managed Ruleset','Enable the core Cloudflare Managed Ruleset for baseline protection against common web threats.','Security',3,2,'Recommended','High','Easy','Pro or above for the Cloudflare Managed Ruleset. Free zones receive the Free Managed Ruleset. Account-level deployments require eligible Enterprise zones.',NULL,'https://developers.cloudflare.com/waf/managed-rules/','Deploy the Cloudflare Managed Ruleset at the account or zone level with explicit hostname coverage. Before removing a zone deployment, verify that the account execute expression covers those hosts. Create exceptions for confirmed false positives, scoped to specific rule IDs and affected operations.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(5,'Enable Stricter WAF Rule: XSS','Enable the specific WAF Managed Rule for XSS, HTML Injection.','Security',3,2,'Situational','Medium','Easy','Cloudflare Managed Ruleset deployed (Pro or above).','Enable Rule ID: 882b37d6bd5f4bf2a3cdb374d503ded0','https://developers.cloudflare.com/waf/managed-rules/reference/cloudflare-managed-ruleset/','Rule 882b37d6bd5f4bf2a3cdb374d503ded0 was disabled with default action Block in managed version 407 on 2026-10-15. Review current metadata and traffic before enabling an override; defaults can change.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(6,'Enable Stricter WAF Rule: Path Anomalies','Enable the WAF Managed Rule for URL Path Anomalies (Multiple Slashes, Relative Paths, CR, LF, NULL).','Security',3,2,'Situational','Medium','Easy','Cloudflare Managed Ruleset deployed (Pro or above).','Enable Rule ID: 6e759e70dc814d90a003f10424644cfb','https://developers.cloudflare.com/waf/managed-rules/reference/cloudflare-managed-ruleset/','Rule 6e759e70dc814d90a003f10424644cfb was disabled with default action Block in managed version 407 on 2026-10-15. Test application path handling before enabling it; review current metadata.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(7,'Observe Large Request Bodies with the Managed Rule','Enable the WAF Managed Rule for anomalously large request bodies.','Security',3,2,'Situational','Medium','Easy','Cloudflare Managed Ruleset deployed (Pro or above).','Review Rule ID 7b822fd1f5814e17888ded658480ea8f (Anomaly:Body - Large 2). Enable only with an explicitly chosen action after testing upload endpoints.','https://developers.cloudflare.com/waf/managed-rules/reference/cloudflare-managed-ruleset/','In managed version 407 on 2026-10-15 this rule was disabled with default action Log, not Block. Enabling it alone does not guarantee mitigation. A large body is not proof of malware; use malicious uploads detection for binary uploads and define an endpoint-specific size policy.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(8,'Enable Stricter WAF Rule: Non Standard Port','Enable the WAF Managed Rule to block requests targeting non-standard HTTP/S ports (not 80 or 443).','Security',3,2,'Situational','Medium','Easy','Cloudflare Managed Ruleset deployed (Pro or above).','Enable Rule ID: 8e361ee4328f4a3caf6caf3e664ed6fe','https://developers.cloudflare.com/waf/managed-rules/reference/cloudflare-managed-ruleset/','Rule 8e361ee4328f4a3caf6caf3e664ed6fe was disabled with default action Block in managed version 407 on 2026-10-15. Alternatively use a scoped custom rule with not cf.edge.server_port in {80 443}. Retain application ports that are intentionally exposed.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(9,'Enable Stricter WAF Rule: Unusual/Unknown HTTP Method','Enable WAF Managed Rules for unusual or unknown HTTP Methods.','Security',3,2,'Situational','Medium','Easy','Cloudflare Managed Ruleset deployed (Pro or above).','Enable Rule IDs: ab53f93c9b03472ab34a5405d9bdc7d5, 6e2240ffcb87477bbd4881b6fd13142f','https://developers.cloudflare.com/waf/managed-rules/reference/cloudflare-managed-ruleset/','Rules ab53f93c9b03472ab34a5405d9bdc7d5 and 6e2240ffcb87477bbd4881b6fd13142f were disabled with default action Block in managed version 407 on 2026-10-15. Standard API and CORS methods are not inherently malicious; check endpoint contracts before overriding.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(10,'Enable Stricter WAF Rule: Vulnerability Scanners','Review vulnerability-scanner rules against expected security testing and your application stack. Enable selected disabled rules rather than overriding every scanner rule indiscriminately.','Security',3,2,'Situational','Medium','Easy','Cloudflare Managed Ruleset deployed (Pro or above).','Refer to WAF Managed Ruleset documentation for specific Rule IDs.','https://developers.cloudflare.com/waf/managed-rules/reference/cloudflare-managed-ruleset/','Current managed definitions must be inspected: in version 407, rule 0242110ae62e44028a13bf4834780914 was already enabled while 223829d453cc4a0e9324811f3a9dc737 was disabled. Default definitions are not proof of effective zone/account enforcement; inspect execute rules and overrides.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(11,'Log Matched Rule Payload','If needed for diagnostics, enable payload logging for matched WAF rules.','Security',3,2,'Optional','Medium','Easy','Enterprise WAF with payload logging entitlement; Super Administrator to configure it; a customer-managed encryption key pair.','Configure via WAF Managed Rules settings.','https://developers.cloudflare.com/waf/managed-rules/payload-logging/','Upload the public key and retain the private key securely outside Cloudflare. Logging captures matched payloads only after enablement; Cloudflare cannot decrypt them and will not request the private key. Preserve payload logging configuration when patching execute rules.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(12,'Scope Browser Integrity Check Exceptions to Non-Browser Traffic','If Browser Integrity Check causes confirmed false positives for APIs or legitimate automation, disable it only for those requests rather than disabling the protection zone-wide.','Security',3,2,'Situational','Medium','Easy','Proxied DNS Records','Use a Configuration Rule scoped to the affected hostname/path, or a narrowly scoped custom Skip rule selecting the Browser Integrity Check product.','https://developers.cloudflare.com/waf/tools/browser-integrity-check/','BIC is outside the normal WAF phases: skipping a Ruleset Engine phase does not skip BIC. Retain checks for other traffic and keep origin authentication in place.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(13,'Deploy OWASP Core Ruleset','If required, review and deploy the OWASP Core Ruleset. Adapt to your needs.','Security',3,2,'Situational','High','Easy','Pro or above; Enterprise for Log action.','Enable via the Zone Security Settings.','https://developers.cloudflare.com/waf/managed-rules/reference/owasp-core-ruleset/','Cloudflare documents false positives and only marginal benefit on top of the Cloudflare Managed Ruleset plus WAF attack score. Start with low paranoia and a high anomaly threshold, preferably Log where available. Tune against traffic; there is no universal safe threshold. Use Managed Challenge only for browser navigations and narrow specific-rule exceptions for confirmed false positives.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(14,'Exempt Selected Verified Bots from Specific Mitigations','Use verified bot categories to exempt only the crawlers or monitoring services that the application needs from bot-specific mitigations.','Security',4,2,'Recommended','Medium','Medium',NULL,'(http.host eq "www.example.com" and http.request.method in {"GET" "HEAD"} and cf.verified_bot_category in {"Search Engine Crawler" "Monitoring & Analytics"})','https://developers.cloudflare.com/bots/concepts/bot/verified-bots/','Example categories and hostname must be adapted. Skip is an exemption from selected rules/products, not a general Allow. Never skip authentication, mTLS, or API validation just because a request is a verified bot. Skip only the offending rule IDs or required phases and place the exception before those rules. Broad verified-bot exemptions can also exempt AI crawlers.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(15,'Use Authenticated, Narrow API Exceptions','For a confirmed API false positive, exempt a precise operation and a verified identity from only the responsible mitigation. A client-supplied header or a high attack score is not authentication.','Security',4,2,'Situational','Medium','Medium','mTLS enabled on the example hostname and valid client certificates issued to the intended integration; alternatively use verified JWT claims with the appropriate entitlement.','(http.host eq "api.example.com" and http.request.uri.path eq "/api/resources" and http.request.method eq "GET" and cf.tls_client_auth.cert_verified and not cf.tls_client_auth.cert_revoked)','https://developers.cloudflare.com/waf/custom-rules/skip/','Restrict the example to the intended certificate identity/CA when multiple clients share the hostname. Do not trust x-api-shield, Authorization presence, a bot score, or WAF score as identity. Select individual managed rule IDs for a managed-rule exception; do not skip schema/JWT checks or all remaining authentication rules.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(16,'Customize Responses for Blocked Requests','Return a short branded or machine-readable error for blocked requests. A WAF Block response is an error response, not an HTTP redirect.','Security',4,2,'Situational','Low','Medium','Pro or above for custom Block responses.','For an existing custom rule with action Block, choose response type application/json, status 403, and body {"error":"Forbidden"}. Use Redirect Rules for an actual supported HTTP redirect.','https://developers.cloudflare.com/waf/custom-rules/create-dashboard/#configure-a-custom-response-for-blocked-requests','Custom-rule Block responses support status codes 400-499 and at most 2 KB. An HTML meta refresh relies on browser behavior and is unsuitable for APIs. Do not send blocked clients to a plaintext HTTP URL.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(17,'Block Fallthrough API Requests (API Shield)','If using API Shield with a positive security model, create a WAF rule to block requests to API hostnames that do not match any saved and defined operation/endpoint.','Security',9,6,'Recommended','High','Easy',NULL,'(http.host in {"api.example.com"} and cf.api_gateway.fallthrough_detected)','https://developers.cloudflare.com/ruleset-engine/rules-language/fields/reference/cf.api_gateway.fallthrough_detected/','Enforces positive security model. Requires a Cloudflare API Shield subscription.','2025-04-22 08:24:32','2026-10-03 23:29:12');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(18,'Observe Methods Unexpected for a Specific Endpoint','Compare request methods to the contract of a particular endpoint rather than treating standard methods such as POST, HEAD, OPTIONS, PATCH, or DELETE as inherently suspicious.','Security',4,2,'Situational','Low','Easy','Enterprise for a custom rule with Log action.','(http.host eq "www.example.com" and http.request.uri.path eq "/public/about" and not http.request.method in {"GET" "HEAD"})','https://developers.cloudflare.com/ruleset-engine/rules-language/fields/reference/http.request.method/','Use Log initially. The example represents a read-only page; change the method set for your endpoint and preserve required CORS OPTIONS requests. Where Log is unavailable, inspect analytics before deploying a narrow policy.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(19,'Mitigate Likely Malicious Requests (WAF Attack Score)','Create a WAF Custom Rule to challenge or block requests with a low WAF Attack Score (indicating likely SQLi, XSS, RCE).','Security',4,2,'Recommended','Medium','Easy','Attack score detection enabled. The numeric cf.waf.score field is documented for Enterprise; cf.waf.score.class requires Business or above. Validate actual entitlement.','(cf.waf.score lt 20)','https://developers.cloudflare.com/ruleset-engine/rules-language/fields/reference/cf.waf.score/','Lower scores are more suspicious; 100 means unscored, not clean. The September 2026 announcement describes wider availability, but the field references still specify Enterprise for numeric scores and Business for classes as of 2026-10-15. Confirm with validation rather than assuming rollout completion. Observe a scoped threshold first (Log requires Enterprise), then Block for APIs or Managed Challenge for browser navigations. Handle reported detection failures explicitly.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(20,'Mitigate Traffic from Managed IP Lists','Create WAF Custom Rules to block or challenge traffic based on Cloudflare Managed IP Lists (Anonymizers, Botnets, Malware, Open Proxies, VPNs).','Security',4,14,'Recommended','High','Easy','Enterprise for Cloudflare Managed IP Lists.','(ip.src in $cf.botnetcc or ip.src in $cf.malware)','https://developers.cloudflare.com/waf/tools/lists/managed-lists/','The documented list names are $cf.botnetcc, $cf.malware, $cf.open_proxies, $cf.anonymizer, and $cf.vpn. Shared infrastructure, VPNs, and anonymizers can be legitimate: use endpoint scope and observed traffic before enforcing broad restrictions.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(21,'Mitigate Tor Traffic (WAF Rule)','Create a WAF Custom Rule to block or challenge traffic originating from the Tor network if it is unwanted.','Security',4,2,'Situational','Medium','Easy',NULL,'(ip.src.continent eq "T1")','https://developers.cloudflare.com/ruleset-engine/rules-language/fields/reference/ip.src.continent/','Ensure Onion Routing feature is disabled in the Zone Network Settings if blocking Tor.','2025-04-22 08:24:32','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(22,'Mitigate Unwanted (ASNs) Networks','Create WAF Custom Rules (preferably using Lists) to block or challenge traffic from specific Autonomous System Numbers (ASNs), such as unwanted cloud providers / infrastructure or specific networks.','Security',4,2,'Situational','High','Easy','','(http.host eq "www.example.com" and ip.src.asnum in {64500})','https://developers.cloudflare.com/ruleset-engine/rules-language/fields/reference/ip.src.asnum/','The ASN is an illustrative placeholder, not a deny recommendation. Build a list from observed abuse and business policy; large cloud/CDN ASNs also host customers, webhooks, and monitoring. Enterprise supports custom ASN lists; other plans can use supported inline values or IP lists. Geo/ASN signals are not authentication.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(23,'Apply Approved Geographic Access Policies','Apply an explicitly approved regional policy to the relevant application using IP geolocation. Do not present a static country list as an OFAC sanctions implementation.','Security',4,2,'Situational','Medium','Easy','A current business/legal policy defining allowed locations and exceptions.','(http.host eq "regional.example.com" and not ip.src.country in {"US" "GB"})','https://developers.cloudflare.com/ruleset-engine/rules-language/fields/reference/ip.src.country/','US and GB are illustrative allowed locations, not a sanctions recommendation. Sanctions can target persons, entities, sectors, and regions; a country allow/deny rule is not sufficient sanctions screening. Geolocation can be inaccurate and VPNs change apparent location. Prefer identity-based controls for private applications.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(24,'Block Known Bot User-Agents','Create a WAF Custom Rule to block requests with User-Agent strings commonly used by unwanted bots (e.g., curl, go-http-client, empty).','Security',4,2,'Situational','Low','Easy',NULL,'(lower(http.user_agent) contains "python" or lower(http.user_agent) contains "go-http-client" or lower(http.user_agent) contains "scrapy" or lower(http.user_agent) contains "libwww-perl" or lower(http.user_agent) contains "fasthttp" or lower(http.user_agent) contains "undici" or lower(http.user_agent) contains "curl" or lower(http.user_agent) contains "wget" or http.user_agent eq "")','https://developers.cloudflare.com/ruleset-engine/rules-language/fields/reference/http.user_agent/','User-Agent is client-controlled and easily spoofed. curl, Python, Go, and empty headers can be legitimate integrations. Scope to browser-only hosts/paths and inventory legitimate automation before blocking; this signal is not a strong bot identity.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(25,'Restrict WordPress (WP) Admin Access (IP/Access)','For WordPress (WP) sites, restrict (block) access to /wp-admin using a WAF Custom Rule matching specific source IPs (preferably via List) or (highly recommended) implement Zero Trust using Cloudflare Access.','Security',10,2,'Recommended','High','Easy','An account IP list named allowed_ips containing trusted source addresses, or a separately configured Access application.','(http.host eq "www.example.com" and (http.request.uri.path eq "/wp-admin" or starts_with(http.request.uri.path, "/wp-admin/") or http.request.uri.path eq "/wp-login.php") and http.request.uri.path ne "/wp-admin/admin-ajax.php" and not ip.src in $allowed_ips)','https://developers.cloudflare.com/waf/tools/lists/','Action: Block. The path boundary avoids matching unrelated prefixes. Preserve public AJAX and any other plugin/form callbacks that your site needs after testing. Prefer Cloudflare Access for identity-based administration; an IP allowlist is not a substitute for WordPress authentication.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(26,'Protect Employee Portals with Identity-Based Access','Protect internal applications with Cloudflare Access and verified identity policies. Geography is an optional additional restriction, not proof that the requester is an employee.','Security',10,2,'Recommended','Medium','Easy',NULL,'Configure an Access application for portal.example.com with explicit identity policies. Optional regional restriction: (http.host eq "portal.example.com" and not ip.src.country in {"US" "GB"}).','https://developers.cloudflare.com/waf/custom-rules/use-cases/allow-traffic-from-specific-countries/','Example countries must follow your policy and travel requirements. Protect the origin from direct bypass and validate Access JWTs. Access has separate Zero Trust plans; an Enterprise website plan is not a prerequisite for basic Access.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(27,'Enforce mTLS Authentication','For specific hostnames requiring mutual TLS, create a WAF Custom Rule to block requests without a valid, verified client certificate.','Security',10,10,'Recommended','High','Easy','Client certificates installed and mTLS enabled for each protected hostname. Cloudflare-issued client certificates are available on all plans within quota; BYOCA requires Enterprise.','(http.host in {"mtls.example.com" "mtls2.example.com"} and (not cf.tls_client_auth.cert_verified or cf.tls_client_auth.cert_revoked))','https://developers.cloudflare.com/learning-paths/mtls/mtls-app-security/related-features/#waf-for-client-certificates','Configure a blocking policy for missing, invalid, or revoked certificates after enabling mTLS. Zone-level client certificates, Access mTLS Service Auth, and Authenticated Origin Pulls are separate products with different purposes and entitlements.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(28,'Block Revoked mTLS Certificates','Enhance mTLS by also blocking requests presenting a revoked client certificate.','Security',10,10,'Recommended','High','Easy','Zone-level mTLS configured, client certificate inventory, and a revocation process.','(http.host in {"mtls.example.com"} and (not cf.tls_client_auth.cert_verified or cf.tls_client_auth.cert_revoked))','https://developers.cloudflare.com/learning-paths/mtls/mtls-app-security/related-features/#certificate-revocation','Reject revoked certificates in addition to requiring successful verification. Test revocation with a real client and maintain safe certificate rotation. Access mTLS has separate Zero Trust plan requirements; do not conflate it with zone-level client certificates.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(29,'Allow Specific mTLS Client Certificates','For granular control, create WAF rules to allow mTLS access only for specific client certificate serial numbers or even the issuer Subject Key Identifier (SKI) hash on certain hostnames.','Security',10,10,'Situational','Medium','Easy','mTLS configured on the intended hostname and an approved client-certificate inventory.','(http.host eq "mtls.example.com" and (not cf.tls_client_auth.cert_verified or cf.tls_client_auth.cert_revoked or not cf.tls_client_auth.cert_serial in {"SPECIFIC_SERIAL_NUMBER"}))','https://developers.cloudflare.com/api-shield/security/mtls/configure/#create-an-mtls-rule','Action: Block. Replace the serial placeholder with an actual approved value. A serial allowlist must also require successful validation and reject revoked certificates; serial numbers alone are not identity and are not globally unique across issuers. Pin the expected issuer or fingerprint where appropriate and plan rotation.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(30,'Mitigate Admin JWT Requests with Low WAF Attack Scores','For authenticated admin operations, combine verified JWT claims with a low WAF attack score to identify suspicious requests. Lower scores indicate higher attack risk.','Security',9,2,'Situational','Medium','Easy','API Shield JWT validation configuration and Enterprise numeric WAF attack score detection enabled.','(http.host eq "api.example.com" and starts_with(http.request.uri.path, "/admin/") and any(cf.api_gateway.tokens.valid[*] eq "<TOKEN_CONFIGURATION_ID>") and lookup_json_string(http.request.jwt.claims["<TOKEN_CONFIGURATION_ID>"][0], "user") eq "admin" and cf.waf.score lt 40)','https://developers.cloudflare.com/waf/custom-rules/use-cases/check-jwt-claim-to-protect-admin-user/','Threshold 40 is illustrative; observe matches before enforcement. Use Block for non-interactive API requests. Independently require a valid token, the expected issuer/audience/claims, and application authorization: this rule does not reject unauthenticated requests by itself.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(31,'Log Likely Automated Traffic (Bot Score)','Create a WAF Custom Rule with Log action to gain visibility into traffic Cloudflare classifies as likely automated based on Bot Score.','Security',6,4,'Recommended','Low','Easy',NULL,'(cf.bot_management.score lt 30 and not cf.bot_management.verified_bot and not cf.bot_management.static_resource)','https://developers.cloudflare.com/waf/custom-rules/use-cases/challenge-bad-bots/','Adjust threshold as needed. Requires a Cloudflare Enterprise Bot Management subscription.','2025-04-22 08:24:32','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(32,'Enforce JavaScript Detections (JSD)','Enforce JavaScript Detections on selected browser navigation endpoints after the visitor has already received an HTML page with the detection script.','Security',6,4,'Situational','High','Easy','Requires a Cloudflare Enterprise Bot Management subscription.','(http.host eq "www.example.com" and http.request.uri.path eq "/account/overview" and http.request.method eq "GET" and not cf.bot_management.js_detection.passed and not cf.bot_management.verified_bot and not cf.bot_management.static_resource)','https://developers.cloudflare.com/cloudflare-challenges/challenge-types/javascript-detections/#enforcing-execution-of-javascript-detections','Action: Managed Challenge, not unconditional Block. JSD must be enabled and CSP must permit it. Choose a post-entrypoint HTML navigation; do not use on first visits, APIs, native apps, or WebSockets. A failed or absent result can be legitimate.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(33,'Mitigate IPv6 Traffic (If Unwanted)','If IPv6 is not needed or desired, create a WAF Custom Rule to block or challenge traffic from IPv6 source addresses.','Security',4,2,'Situational','Low','Easy',NULL,'(ip.src in {::/0})','https://developers.cloudflare.com/network/ipv6-compatibility/','IPv6 is not inherently malicious. Broadly blocking it can exclude legitimate clients; prefer prefix-aware abuse controls when available. Check the documented availability before proposing to disable IPv6 compatibility: it cannot be disabled on every plan.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(34,'Use Account Takeover (ATO) Detections','Leverage Cloudflare Enterprise Bot Management Detection IDs in WAF or Rate Limiting rules to mitigate predictable bot behavior like login failures.','Security',6,4,'Recommended','High','Easy','Cloudflare Enterprise Bot Management subscription.','(http.host eq "www.example.com" and starts_with(http.request.uri.path, "/login") and http.request.method in {"POST"} and any(cf.bot_management.detection_ids[*] in {201326592}))','https://developers.cloudflare.com/bots/additional-configurations/detection-ids/','Consider also implementing Turnstile, a CAPTCHA alternative.','2025-04-22 08:24:32','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(35,'Mitigate Disposable Email Signups','Use Cloudflare Fraud Detection features via WAF rules to block, challenge, log, or rate limit signups using known disposable email domains.','Security',14,2,'Recommended','Medium','Easy',NULL,'(http.host eq "www.example.com" and http.request.uri.path eq "/api/user/create" and http.request.method in {"POST"} and cf.fraud_detection.disposable_email)','https://blog.cloudflare.com/cloudflare-fraud-detection/','Cloudflare Fraud Detection is in early access. Contact your account team.','2025-04-22 08:24:32','2026-10-03 23:29:12');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(36,'Mitigate Logins with Leaked Credentials','Use Leaked Credentials Detection via WAF or Rate Limiting rules to challenge or block login attempts using credentials (passwords) known to be leaked (HIBP), or forward this info to the origin server to trigger password resets for specific users.','Security',14,2,'Recommended','High','Easy','Leaked credentials detection enabled with correctly configured authentication detection locations. password_leaked is available on all plans; username_and_password_leaked requires Pro or above.','(http.host eq "www.example.com" and http.request.uri.path eq "/api/login" and http.request.method eq "POST" and cf.waf.credential_check.username_and_password_leaked)','https://developers.cloudflare.com/waf/detections/leaked-credentials/','The example uses the more precise leaked username/password pair (Pro or above); Free can use password_leaked with greater false-positive risk. Prefer a recovery/password-reset workflow over blindly rejecting legitimate users. Use non-interactive controls for API login requests and decide how detection failures are handled.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(37,'Implement Time-Based Rules','Use the `http.request.timestamp.sec` field in WAF rules to apply logic based on specific time periods (e.g., block POSTs during maintenance window).','Security',4,2,'Situational','Low','Easy',NULL,'(http.host eq "www.example.com" and http.request.method eq "POST" and http.request.timestamp.sec ge 1792022400 and http.request.timestamp.sec lt 1792026000)','https://developers.cloudflare.com/ruleset-engine/rules-language/fields/reference/http.request.timestamp.sec/','Example only: 2026-10-15 00:00-01:00 UTC. Replace the window before deploying and use explicit start/end boundaries. The field is integer UNIX epoch seconds, not a fixed-width 10-digit string; remove or disable expired maintenance rules.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(38,'Mitigate Unauthorized Worker Subrequests','Prevent abuse from other Cloudflare Workers by using the WAF rules to block subrequests originating from unknown Cloudflare Workers.','Security',4,18,'Situational','Medium','Easy',NULL,'(http.host eq "www.example.com" and not cf.worker.upstream_zone in {"" "example.com"})','https://developers.cloudflare.com/ruleset-engine/rules-language/fields/reference/cf.worker.upstream_zone/','Use the Rules field, not the client-supplied CF-Worker header. Inventory legitimate partner and SaaS/O2O Worker traffic before enforcement. The upstream zone identifies a calling zone, not an authorized user; retain application authentication.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(39,'IP-based Rate Limiting for Logins','Protect login endpoints by creating a Rate Limiting rule that tracks and limits login attempts per IP address over a time window.','Security',5,3,'Recommended','High','Easy','Business or eligible Enterprise for this hostname+method expression; Free/Pro must simplify to fields their rate limiting plan supports.','Match: (http.host eq "www.example.com" and http.request.uri.path eq "/login" and http.request.method eq "POST"). API characteristics: ["ip.src", "cf.colo.id"]. Set threshold, counting period, and mitigation timeout from observed traffic. Action: Block; Log is Enterprise-only.','https://developers.cloudflare.com/waf/rate-limiting-rules/parameters/','Counters are per data center, not a precise global quota. Consider IP with NAT support where available to avoid aggregating unrelated users. Authenticated identities require appropriate advanced characteristics. Do not use interstitial challenges for non-interactive API clients.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(40,'Rate Limit Uploads','Prevent excessive uploads by creating a Rate Limiting rule based on IP address or session, targeting POST/PUT/PATCH methods on upload endpoints.','Security',5,3,'Situational','Medium','Easy','Business or eligible Enterprise for method-based matching; Advanced Rate Limiting for session-based characteristics.','Match: (http.host eq "www.example.com" and http.request.uri.path eq "/upload" and http.request.method in {"POST" "PUT" "PATCH"}). API characteristics: ["ip.src", "cf.colo.id"]. Action: Block, with measured threshold, counting period, and mitigation timeout.','https://developers.cloudflare.com/waf/rate-limiting-rules/best-practices/','Throttle is action behavior, not an action name. Where the Enterprise contract permits it, configure Block with mitigation_timeout: 0 to throttle excess requests. Rate limits do not impose file-size limits or scan uploads for malware.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(41,'Rate Limit Credential Stuffing','Mitigate credential stuffing by rate limiting login attempts based on session (cookie/header) or IP or other characteristics, potentially with lower thresholds than general login limiting.','Security',5,3,'Recommended','High','Easy','Enterprise with Advanced Rate Limiting for cookie/header/custom characteristics.','Match: (http.host eq "www.example.com" and http.request.uri.path eq "/login" and http.request.method eq "POST"). API characteristics for an IP limit: ["ip.src", "cf.colo.id"]. Create a separate identity-based rule when a validated session/user identifier is available. Action: Block.','https://developers.cloudflare.com/waf/rate-limiting-rules/best-practices/#protecting-against-credential-stuffing','Combining IP and a rotatable cookie in one key creates a counter per combination and may make evasion easier; it is not two independent limits. Repeat the intended scope in a custom counting expression. Response-based counting requires Business or eligible Enterprise and can bypass cache. Throttling is Enterprise Block behavior, not a separate action.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(42,'Rate Limit Logins with Leaked Passwords','Create a Rate Limiting rule specifically targeting login attempts (authentication events) detected using leaked passwords (HIBP).','Security',5,3,'Recommended','High','Easy','Eligible Enterprise rate limiting with leaked-credentials fields; enable leaked credentials detection. Advanced Rate Limiting is needed for session/custom characteristics.','Match: (http.host eq "www.example.com" and http.request.uri.path eq "/login" and http.request.method eq "POST" and cf.waf.credential_check.username_and_password_leaked). API characteristics: ["ip.src", "cf.colo.id"]. Use an observed threshold and Block action.','https://developers.cloudflare.com/waf/detections/leaked-credentials/examples/','Leaked username/password pairs reduce false positives compared with password-only detection. Scope to the actual authentication endpoint and provide account-recovery paths. A detection returning no result is not proof that credentials are safe.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(43,'Geography-based Rate Limiting','If certain countries generate unexpected amounts of traffic, apply rate limiting based on the IP address or other relevant characteristics.','Security',5,3,'Situational','Low','Easy','A rate limiting plan/contract supporting country-based expressions; verify availability before deploying.','Characteristics: IP Address. Match `ip.src.country in {"DE" "ES"}`.','https://developers.cloudflare.com/waf/rate-limiting-rules/use-cases/','Use observed traffic and an approved regional policy, not a list of supposedly malicious countries. Scope to the intended hostname/operation and include cf.colo.id in API characteristics; counters are per data center.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(44,'IPv6 Prefix Rate Limiting','Protect against abuse from entire IPv6 prefixes by rate limiting using the `cidr6()` function in custom characteristics.','Security',5,3,'Situational','Medium','Easy','Enterprise with Advanced Rate Limiting and Custom characteristics.','Match: (http.host eq "www.example.com" and http.request.uri.path eq "/login" and http.request.method eq "POST"). API characteristics: ["cidr6(ip.src, 64)", "cf.colo.id"]. Set rate/period/action from measured traffic.','https://developers.cloudflare.com/ruleset-engine/rules-language/functions/#cidr6','cidr6 passes IPv4 through unchanged. /64 is a starting point for subscriber-prefix aggregation, not a universal identity; /48 combines many more clients. Confirm assignment patterns and false positives before changing prefix length. Without Advanced Rate Limiting, use supported IP or IP with NAT support characteristics.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(45,'Client Certificate Rate Limiting (mTLS)','Prevent abuse of compromised mTLS certificates or devices by rate limiting requests based on the client certificate fingerprint.','Security',5,10,'Situational','Medium','Easy','mTLS enabled on the hostname, Cloudflare certificate forwarding configured, and Enterprise Advanced Rate Limiting for header characteristics.','Match: (http.host eq "mtls.example.com" and cf.tls_client_auth.cert_verified and not cf.tls_client_auth.cert_revoked). With certificate forwarding enabled, use the authoritative cf-client-cert-sha256 header value as the characteristic and include cf.colo.id in the API configuration.','https://developers.cloudflare.com/learning-paths/mtls/mtls-app-security/related-features/#rate-limiting-by-client-certificates','Configure and verify Cloudflare certificate forwarding first; do not trust an arbitrary client-provided fingerprint header. Header names in API expressions are lowercase. Rate limiting does not replace rejecting invalid/revoked certificates. Validate header availability and empty-value behavior on real mTLS requests.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(46,'JavaScript Detection (JSD) Rate Limiting','Rate limit repeated missing/failed JSD results only on browser navigation endpoints that are visited after an HTML bootstrap page.','Security',5,4,'Situational','Medium','Easy','Enterprise Bot Management with JSD enabled and an Enterprise rate limiting entitlement; response counting fields must be available.','Match: (http.host eq "www.example.com" and http.request.uri.path eq "/account/overview" and http.request.method eq "GET" and not cf.bot_management.js_detection.passed and not cf.bot_management.verified_bot). API characteristics: ["ip.src", "cf.colo.id"]. If counting HTML responses, repeat the full match expression and add any(http.response.headers["content-type"][*] contains "text/html").','https://developers.cloudflare.com/ruleset-engine/rules-language/fields/reference/cf.bot_management.js_detection.passed/','A counting expression replaces the default match expression for counting; an HTML-only counter without the original scope can count unrelated traffic. Response fields can bypass cache. Do not apply this to first visits, APIs, WebSockets, or native apps. Use browser-appropriate mitigation and retain a safe bootstrap path.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(47,'Implement Turnstile on Forms','Use Cloudflare Turnstile (managed mode recommended) on login, signup, or other forms to distinguish humans from bots without complex CAPTCHAs. Turnstile can also be used with WebViews on mobile devices.','Security',6,8,'Recommended','High','Medium',NULL,'Requires client-side integration and server-side validation using Siteverify API.','https://developers.cloudflare.com/turnstile/get-started/server-side-validation/','Your backend must call Siteverify and reject invalid tokens before performing the protected action. Keep the secret server-side and validate expected hostname/action when used. Tokens expire after 300 seconds and are single-use; refresh expired/redeemed tokens. Optional pre-clearance does not replace Siteverify or application authentication.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(48,'Monitor Client-side Scripts with Client-side Security','Use Client-side security (formerly Page Shield) to monitor the scripts, connections, and cookies loaded by your pages and get alerted to changes or malicious resources.','Security',13,7,'Recommended','High','Easy','Proxied DNS Records','Enable Client-side security monitoring and configure alerts in Notifications.','https://developers.cloudflare.com/client-side-security/','Script monitoring is available on all plans; connection and cookie monitoring and alerts require Business or above. Malicious script detection and content security rules (positive security model, PCI DSS v4.0 requirement 6.4.3) require Client-Side Security Advanced (formerly the Page Shield add-on).','2025-04-22 08:24:32','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(49,'Use Advanced Certificate Manager (ACM)','Use Advanced Certificate Manager when you need its additional hostname coverage or certificate customization; Universal SSL remains appropriate when it meets your requirements.','Security',2,15,'Situational','Medium','Easy','Advanced Certificate Manager paid add-on; validate required certificate and TLS capabilities separately.',NULL,'https://developers.cloudflare.com/ssl/edge-certificates/advanced-certificate-manager/','ACM is not required just to enable TLS 1.3, Always Use HTTPS, or a minimum TLS version. Confirm full hostname coverage and successful certificate deployment before replacing an existing edge certificate.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(50,'Disable Universal SSL Only with Verified Replacement Coverage','Keep Universal SSL unless there is a specific reason to remove it. If disabling it, verify active replacement edge certificates cover every required hostname first.','Security',2,5,'Situational','Low','Easy','Active ACM or custom edge certificates with complete hostname coverage and a documented renewal/recovery process.',NULL,'https://developers.cloudflare.com/ssl/edge-certificates/universal-ssl/','An origin certificate is not an edge certificate. Disabling Universal SSL can break HTTPS on uncovered hostnames. Confirm certificate status, expiry, apex/wildcard coverage, and recovery before making the zone change.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(51,'Set Minimum TLS Version to 1.2','Configure Cloudflare to only allow TLS 1.2 or higher connections for improved security.','Security',2,5,'Recommended','High','Easy',NULL,NULL,'https://developers.cloudflare.com/ssl/edge-certificates/additional-options/minimum-tls/','Enable TLS 1.3. Recommended option for compliance and security.','2025-04-22 08:24:32','2026-10-03 23:29:12');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(52,'Enable Always Use HTTPS','Force all visitor connections to use HTTPS.','Security',2,5,'Mandatory','High','Easy',NULL,NULL,'https://developers.cloudflare.com/ssl/edge-certificates/additional-options/always-use-https/','Consider also enabling HSTS as well. Preferably disable plaintext HTTP entirely.','2025-04-22 08:24:32','2026-10-03 23:29:12');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(53,'Enable Automatic HTTPS Rewrites','Allow Cloudflare to automatically rewrite HTTP links to HTTPS in HTML source code.','Security',2,5,'Recommended','Low','Easy',NULL,NULL,'https://developers.cloudflare.com/ssl/edge-certificates/additional-options/automatic-https-rewrites/','Helps prevent mixed content warnings. Review your application source code.','2025-04-22 08:24:32','2026-10-03 23:29:12');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(54,'Enable HTTP/2 and HTTP/3','Enable modern HTTP protocols (HTTP/2, HTTP/3 QUIC) for performance and security improvements.','Performance',8,5,'Recommended','Medium','Easy',NULL,NULL,'https://developers.cloudflare.com/speed/optimization/protocol/http3/','Review the Speed Optimization features.','2025-04-22 08:24:32','2025-04-22 08:24:32');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(55,'Enable HTTP/2 to Origin','Allow Cloudflare to use HTTP/2 when connecting to your origin servers if supported.','Performance',8,5,'Recommended','Medium','Easy','Origin server also needs to support HTTP/2 protocol',NULL,'https://developers.cloudflare.com/speed/optimization/protocol/http2-to-origin/','Requires origin server support for HTTP/2. Adjust the connection multiplexing (request pooling).','2025-04-22 08:24:32','2025-04-22 08:24:32');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(56,'Use Logpush for Comprehensive Logs','Configure Logpush to send detailed Firewall events, HTTP request, or other logs to a storage service (R2, S3) or SIEM.','Security',11,11,'Recommended','Medium','Easy',NULL,NULL,'https://developers.cloudflare.com/logs/logpush/','Logpush is strongly recommended for long-term storage and non-sampled logs. Since Birthday Week 2026 it is available on all plans (pay-as-you-go), including Logpush Transformers to filter, redact, and reformat logs with SQL before delivery.','2025-04-22 08:24:32','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(57,'Set Up Notifications','Configure Cloudflare Notifications - email or webhook alerts - for relevant events (security events, certificate expiry, DDoS attacks, and more).','Security',11,20,'Recommended','Medium','Easy',NULL,NULL,'https://developers.cloudflare.com/notifications/','Review available Notifications and configure them based on your needs. Consider using the Cloudflare API or Terraform for automation.','2025-04-22 08:24:32','2025-04-22 08:24:32');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(58,'Use Terraform for Infrastructure as Code (IaC)','Manage Cloudflare configurations using the Cloudflare Terraform Provider for automation, version control, and consistency.','General',12,12,'Recommended','High','Medium','Knowledge of Terraform, version control systems like Git',NULL,'https://developers.cloudflare.com/terraform/',NULL,'2025-04-22 08:24:32','2025-04-22 08:24:32');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(59,'Use Cloudflare API or SDKs for Automation','Leverage the Cloudflare API or official SDKs for custom automation scripts and integrations.','General',12,13,'Recommended','Medium','Medium','Prior knowledge in SDKs or programming is recommended',NULL,'https://developers.cloudflare.com/fundamentals/api/reference/sdks/',NULL,'2025-04-22 08:24:32','2025-04-22 08:24:32');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(60,'Follow Principle of Least Privilege for Users and Tokens','Assign users (or Groups) and API Tokens only the minimum required permissions using specific Roles and scoped tokens. Opt for System for Cross Domain Identity Management (SCIM) User Groups to centralize and simplify your user and group management at scale by syncing memberships directly with your upstream identity provider (IdP).','Security',12,13,'Mandatory','Medium','Medium',NULL,NULL,'https://developers.cloudflare.com/fundamentals/manage-members/','Use Roles for Dashboard UI access and configure API Token permissions separately. Leverage Account Owned Tokens. Customers can also configure Single-Sign-On (SSO) for the Cloudflare Dashboard.','2025-04-22 08:24:32','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(61,'Enforce Multi-Factor Authentication (MFA)','Require MFA for all users accessing the Cloudflare dashboard.','Security',12,25,'Mandatory','High','Easy','Configure either a TOTP mobile app or a security key to enable 2FA on your account',NULL,'https://developers.cloudflare.com/fundamentals/user-profiles/2fa/','MFA is often a compliance requirement. Customers can also configure Single-Sign-On (SSO) for the Cloudflare Dashboard.','2025-04-22 08:24:32','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(62,'Integrate Single Sign-On (SSO)','If applicable, integrate your identity provider (IdP) with Cloudflare for SSO dashboard access.','Security',12,25,'Recommended','High','Complex','Requires a valid Identity Provider (IdP)',NULL,'https://developers.cloudflare.com/fundamentals/manage-members/dashboard-sso/','Review the Cloudflare SSO documentation for best practices, especially backups (break-glass).','2025-04-22 08:24:32','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(63,'Regularly Review Audit Logs','Periodically review Cloudflare Audit Logs to monitor configuration changes and detect suspicious activity.','Security',11,25,'Recommended','Medium','Easy',NULL,NULL,'https://developers.cloudflare.com/fundamentals/account/account-security/review-audit-logs/',NULL,'2025-04-22 08:24:32','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(65,'Use Authenticated Origin Pulls (mTLS)','Use Authenticated Origin Pulls to require Cloudflare to present a client certificate when connecting to the origin. Use a custom certificate when you need to authenticate your specific configuration.','Security',7,10,'Recommended','High','Complex','Origin-side client certificate verification and Full or Full (strict) mode. Custom/per-hostname certificate options depend on entitlement.',NULL,'https://developers.cloudflare.com/fundamentals/security/protect-your-origin-server/','The shared Cloudflare AOP certificate proves only that traffic comes from the Cloudflare network, not your account or zone. For stronger isolation, upload a customer-specific certificate and trust only its CA at the origin. Also restrict direct origin access and prefer Full (strict) for server certificate verification.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(66,'Rotate Origin IPs After Onboarding','After migrating to Cloudflare and proxying records, change your origin server IP addresses.','Security',7,25,'Recommended','High','Medium','Access to infrastructure management, DNS control',NULL,'https://developers.cloudflare.com/fundamentals/security/protect-your-origin-server/','Rotating an exposed IP is only one layer. Restrict inbound origin traffic to the required trusted sources or use Tunnel; otherwise the new IP can be discovered and used to bypass the WAF. Remove accidental DNS-only exposure and authenticate Cloudflare-to-origin traffic.','2025-04-22 08:24:32','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(67,'Use Transform Rules for Security Headers','Leverage Managed Transforms or create custom Transform Rules to add or modify security response headers.','Security',7,19,'Recommended','Medium','Medium','Understanding of HTTP security headers',NULL,'https://developers.cloudflare.com/rules/transform/managed-transforms/reference/','Use Cloudflare Snippets for more customizable HTTP header modifications or other custom logics.','2025-04-22 08:24:32','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(68,'Implement API Schema Validation','Use API Shield to upload your API schema (OpenAPI) and enforce validation on incoming requests.','Security',9,6,'Recommended','High','Complex','Valid OpenAPI schema document, API Shield subscription',NULL,'https://developers.cloudflare.com/api-shield/security/schema-validation/','The main goal should be to implement a positive security model for your APIs.','2025-04-22 08:24:32','2025-04-22 08:24:32');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(69,'Use API Shield Sequence Mitigation','Define expected sequences of API calls and use Cloudflare API Shield Sequence Mitigation to detect and block out-of-order requests.','Security',9,6,'Recommended','High','Complex',NULL,NULL,'https://developers.cloudflare.com/api-shield/security/sequence-mitigation/','Review the Cloudflare documentation.','2025-04-22 08:24:32','2025-04-22 08:24:32');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(70,'Configure SPF, DMARC, DKIM DNS records','These records help prevent spoofing, phishing, and unauthorized use of your domain by authenticating outgoing emails and instructing mail servers on how to handle suspicious messages.','Security',1,1,'Recommended','Medium','Easy','Cloudflare is the Authoritative DNS provider',NULL,'https://developers.cloudflare.com/dmarc-management/',NULL,'2025-06-14 21:03:01','2025-06-14 21:03:01');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(71,'Mitigating Pretend-Browsers with JavaScript Detections','In scenarios where the BotScore alone may not reliably differentiate between likely human and bots, you can enhance detection by enabling and enforcing JavaScript Detections (JSD).','Security',4,4,'Situational','High','Medium','Enterprise Bot Management; JSD enabled; CSP permits the detection script; an earlier HTML page already bootstraps browser clients.','(http.host eq "www.example.com" and http.request.uri.path eq "/account/overview" and http.request.method eq "GET" and starts_with(http.user_agent, "Mozilla/5.0") and not cf.bot_management.js_detection.passed and not cf.bot_management.verified_bot and not cf.bot_management.static_resource)','https://developers.cloudflare.com/cloudflare-challenges/challenge-types/javascript-detections/#enforcing-execution-of-javascript-detections','Use Managed Challenge on a post-bootstrap browser navigation. The User-Agent is only a weak hint and can be spoofed; it does not prove that JavaScript ran. Exclude first visits and non-browser clients rather than enforcing JSD across all Mozilla requests.','2025-04-23 21:30:37','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(72,'Rate Limit Browser Sessions with Cookie Characteristics','Use cookie-based counters for selected browser workflows, with separate limits for clients that have no valid session and protections against token rotation.','Security',5,3,'Recommended','High','Medium','Requires Cloudflare Advanced Rate Limiting subscription.','For an authenticated session cookie, scope the match to the intended browser endpoint and use the selected cookie value plus cf.colo.id as API characteristics. Treat cf_clearance-based limiting as an optional secondary control.','https://developers.cloudflare.com/waf/rate-limiting-rules/parameters/','cf_clearance records a challenge clearance, not a logged-in user identity. Missing cookies share a missing-value counter and empty values are distinct. Attackers can obtain/rotate cookies, so retain independent IP and authenticated-user limits where needed. Challenge Passage does not universally exempt rate limiting actions.','2025-04-23 21:52:02','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(73,'Replace insecure JavaScript Libraries','Automatically rewrites URLs to external JavaScript libraries to point to Cloudflare-hosted libraries instead, i.e. polyfill.','Security',13,2,'Recommended','Medium','Easy','Proxied DNS Records',NULL,'https://developers.cloudflare.com/waf/tools/replace-insecure-js-libraries/',NULL,'2025-04-24 12:27:52','2025-06-03 08:10:52');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(74,'Block HTTP plaintext requests','Enforce not accepting requests in plaintext / unencrypted HTTP requests with a WAF Custom Rule to block any non-HTTPS (not using SSL/TLS) requests.','Security',4,2,'Situational','High','Easy',NULL,'(not ssl)','https://developers.cloudflare.com/ssl/edge-certificates/additional-options/always-use-https/','Decide whether the application redirects HTTP to HTTPS or rejects it. Always Use HTTPS can answer before the WAF, so enabling both does not guarantee that a not ssl rule blocks plaintext requests. Verify phase order and live behavior. Redirection cannot protect the initial plaintext request; use HSTS for capable clients and require HTTPS in API clients.','2025-04-24 13:22:29','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(75,'Return branded Custom Errors as response','Show personalized branded custom content when security challenges or HTTP errors occur from your origin or Cloudflare.','General',12,19,'Optional','Medium','Medium',NULL,NULL,'https://developers.cloudflare.com/rules/custom-errors/','Only available for paid plans.','2025-04-25 21:50:13','2025-04-25 21:50:13');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(76,'Protect against HTTP DDoS botnets','Keep Cloudflare HTTP DDoS protection and relevant botnet-category rules enabled with their default settings unless a confirmed false positive requires a narrow override.','Security',16,21,'Mandatory','High','Easy','Proxied DNS Records',NULL,'https://developers.cloudflare.com/ddos-protection/managed-rulesets/http/rule-categories/','Historic quarterly percentages describe a reporting period, not a durable property of your traffic. Review current rule categories and DDoS analytics; do not lower protection solely because of a past report.','2025-06-03 06:08:16','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(77,'Protection against common user-agents seen in HTTP DDoS attacks','Use current attack analytics to identify suspicious client patterns, and combine User-Agent with affected hostname/path and additional signals before creating a mitigation.','Security',16,21,'Situational','High','Easy','Proxied DNS Records','(http.host eq "www.example.com" and http.request.uri.path eq "/expensive-search" and lower(http.user_agent) contains "fasthttp")','https://developers.cloudflare.com/ddos-protection/best-practices/proactive-defense/','The example is a weak, spoofable signal, not a universal deny policy. Old browser User-Agent lists become stale and match legitimate browsers; use current observed evidence and plan-supported rate limits. Rules-language inline sets use whitespace separators, not commas.','2025-06-03 06:13:35','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(78,'Protection against common HTTP methods seen in HTTP DDoS attacks','Restrict methods that an endpoint does not support, using its actual application contract rather than historical DDoS method percentages.','Security',16,21,'Situational','Medium','Easy','Proxied DNS Records','(http.host eq "www.example.com" and http.request.uri.path eq "/public/about" and not http.request.method in {"GET" "HEAD"})','https://developers.cloudflare.com/ruleset-engine/rules-language/fields/reference/http.request.method/','DELETE, PATCH, HEAD, and OPTIONS are standard legitimate methods where the application expects them. Account for CORS and API schemas; use a narrow Block policy only for unsupported methods.','2025-06-03 06:28:41','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(79,'Protecting paths most attacked by HTTP DDoS attacks','Protect application-specific expensive or sensitive paths using current traffic evidence, rather than assuming paths from an old DDoS report are abusive everywhere.','Security',16,21,'Recommended','Medium','Easy','Proxied DNS Records','(http.host eq "www.example.com" and (http.request.uri.path eq "/wp-login.php" or starts_with(http.request.uri.path, "/wp-login.php/")))','https://developers.cloudflare.com/ruleset-engine/rules-language/fields/reference/http.request.uri.path/','Match only if WordPress is relevant to your site. ends_with is a function and does not interpret [0-9]+ as a regex; use matches only with supported Business/Enterprise regex entitlement when a true pattern is needed. Use measured rate limits for real login endpoints and Block probes for software you do not run.','2025-06-03 06:34:10','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(80,'Apply Network-Layer Policies with the Appropriate Product','For networks protected by Magic Transit, use Cloudflare Network Firewall policies and current network analytics to restrict unwanted traffic.','Security',16,17,'Optional','Medium','Easy','Magic Transit and the relevant network firewall entitlement; a policy based on your protected prefixes and expected traffic.','Configure a network firewall policy for the required protocol, destination prefix/port, and observed source policy. An HTTP WAF custom rule does not filter L3/L4 packets.','https://developers.cloudflare.com/cloudflare-one/traffic-controls/packet-filtering/','The location of a Cloudflare ingress data center is not the source country of an attacker. Do not copy a historical list of locations into an HTTP country block. Network-layer products and application WAF rules have different scopes.','2025-06-03 06:38:49','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(81,'Protection against common and emerging L3/4 DDoS attack vectors','Magic Transit is a network security and performance solution that offers L3/L4 DDoS protection, traffic acceleration, and more for on-premise, cloud-hosted, and hybrid networks.','Security',16,17,'Situational','High','Complex','Own an IP Prefix for BGP announcement via Cloudflare Magic Transit.',NULL,'https://developers.cloudflare.com/ddos-protection/about/attack-coverage/','Magic Transit requires a separate service/contract and protected-prefix onboarding. HTTP WAF and rate limiting rules do not apply to arbitrary TCP/UDP applications; Spectrum or network-layer products provide the relevant coverage.','2025-06-03 06:42:58','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(82,'Apex Proxying for Cloudflare for SaaS customers','SaaS providers delivering per-tenant traffic from branded IPs, preserving IP reputation, simplifying Firewall allowlisting, and more advantages, are recommended to opt for BYOIP, or alternatively, Static IPs.','General',17,22,'Situational','High','Medium','Enterprise Plan Paid Add-On',NULL,'https://developers.cloudflare.com/cloudflare-for-platforms/cloudflare-for-saas/start/advanced-settings/apex-proxying/','Apex Proxying requires an A DNS Record, and therefore an IP address. This can be achieved by purchasing a Static IP from Cloudflare, or onboarding BYOIP, which offers more flexibility and additional advantages. In some cases however, some Authoritative DNS Providers allow CNAME Flattening.','2025-06-03 06:54:26','2025-06-03 06:54:26');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(83,'Expose Public Hostnames via Cloudflare Tunnel','Use Cloudflare Tunnel to securely expose specific applications from your origin server while blocking all other inbound traffic, effectively shielding your server from potential threats.','Security',7,30,'Situational','Medium','Medium','Ability to install the Cloudflare Tunnel on the origin server',NULL,'https://developers.cloudflare.com/cloudflare-one/networks/connectors/cloudflare-tunnel/','Tunnel creates outbound origin connections and can eliminate public inbound exposure when the origin firewall is configured accordingly. A published hostname is still public unless you add Access or application authentication. Validate Access JWTs at the origin and retain least-privilege ingress configuration.','2025-06-13 08:48:40','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(84,'Enable Argo Smart Routing','Argo Smart Routing avoids network congestion by dynamically choosing the fastest path, improving speed and reliability for users far from your origin.','Performance',8,23,'Situational','Medium','Easy','An Argo/Smart Shield paid service or eligible Enterprise contract/preview; confirm pricing before activation.',NULL,'https://developers.cloudflare.com/argo-smart-routing/','Argo Smart Routing is now offered as part of Smart Shield. Measure origin-bound latency before and after enabling it; cached responses do not need the same origin routing optimization.','2025-06-13 09:04:48','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(85,'Configure Tiered Caching','CDN Tiered Cache improves cache hit ratios and reduces origin load by routing requests through a hierarchy of Cloudflare data centers, limiting origin fetches.','Performance',8,24,'Situational','High','Medium',NULL,NULL,'https://developers.cloudflare.com/cache/how-to/tiered-cache/','Tiered Cache reduces origin fetches for eligible CDN-cached content. Workers fetch can participate in that caching path; the Workers Cache API is data-center-local and does not support Tiered Cache. Distinguish CDN fetch caching, Workers Cache, and the Workers Cache API when choosing an architecture.','2025-06-14 21:19:01','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(86,'Gain visibility into third-party Workers requests','Add a header when a Workers Subrequest comes from another zone with Transform Rules.','Security',4,19,'Situational','Medium','Easy',NULL,'(cf.worker.upstream_zone ne "" and cf.worker.upstream_zone ne "example.com")','https://developers.cloudflare.com/changelog/post/2025-06-09-transform-rule-subrequest-matching/','Use a Request Header Transform Rule to overwrite a diagnostic header from this field, rather than trusting a client-supplied value. The calling zone is useful for provenance, not user authorization. This practice configures Transform Rules, not a Worker.','2025-06-23 13:49:05','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(87,'Avoiding Managed Challenge for APIs','Do not send interstitial Challenge Pages to API, AJAX/XHR, native mobile, or WebSocket clients. Use API authentication, scoped Block/Log policies, and rate limiting; browser frontends may use Turnstile pre-clearance.','Security',4,2,'Recommended','High','Medium','API (AJAX/XHR requests)',NULL,'https://developers.cloudflare.com/cloudflare-challenges/challenge-types/challenge-pages/detect-response/','cf-mitigated: challenge identifies a Challenge Page response; detection alone does not let an API client solve it. Browser pre-clearance requires correct hostname/cookie configuration and does not replace mandatory Siteverify validation of Turnstile tokens or application authorization.','2025-07-29 10:58:52','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(88,'Protect Native Mobile Applications (iOS and Android)','Protect native mobile APIs with validated authentication and, when appropriate, a separately provisioned mobile app/device attestation SDK. Vendor attestation tokens can be validated at the edge or origin.','Security',6,4,'Situational','High','Complex','A documented mobile SDK/vendor integration and its own entitlement; API Shield plus Advanced Rate Limiting for edge JWT-claim rate limits, or equivalent origin validation.',NULL,'https://approov.io/resource/quickstarts/','Approov publishes native-app SDK quickstarts and a Cloudflare Worker token-validation integration. This is not evidence of a universally available Cloudflare-branded Mobile SDK or bundled Enterprise entitlement. Verify the offered integration and contract. Enforce signature, expiry, expected claims, and application authorization; header presence alone must never bypass security. Do not enforce browser JSD on native apps.','2025-08-12 09:54:00','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(89,'Exclude Challenge Pages (cdn-cgi endpoint)','Cloudflare Challenge Pages are isolated for security. Custom headers and policies are blocked, and Transform Rules altering response headers must exclude Challenge paths to avoid failures.','Security',4,2,'Recommended','High','Medium','Response Header Transform Rules or Custom Errors; cf.response.error_type is a response-phase field, not a WAF request field.','not (starts_with(http.request.uri.path, "/cdn-cgi/challenge-platform/") or cf.response.error_type in {"managed_challenge" "iuam" "legacy_challenge" "country_challenge"})','https://developers.cloudflare.com/ruleset-engine/rules-language/fields/reference/cf.response.error_type/','Apply this condition only in supported response phases when modifying headers that could break challenges. Do not block/challenge the challenge-platform endpoint. Avoid blanket exemptions for all /cdn-cgi/ traffic: image and Zaraz paths may represent application requests.','2025-10-07 18:17:52','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(90,'Block Access to Sensitive Files and Paths','Block requests for configuration files, version control metadata, backups, and debugging endpoints that should never be publicly reachable.','Security',4,2,'Recommended','High','Easy',NULL,'(http.host eq "www.example.com" and (lower(http.request.uri.path) contains "/.git" or lower(http.request.uri.path) contains "/.svn" or lower(http.request.uri.path) contains "/.env" or lower(http.request.uri.path) contains "/.htaccess" or lower(http.request.uri.path) contains "/.htpasswd" or lower(http.request.uri.path) contains "/.ds_store" or ends_with(lower(http.request.uri.path), ".sql") or ends_with(lower(http.request.uri.path), ".bak") or ends_with(lower(http.request.uri.path), ".old") or lower(http.request.uri.path) in {"/wp-config.php" "/phpinfo.php"}) and not starts_with(http.request.uri.path, "/.well-known/"))','https://developers.cloudflare.com/waf/custom-rules/use-cases/','Action: Block; a 404 response is appropriate for probes where custom responses are available (Pro or above). Scope the example to your stack and preserve required /.well-known/ resources. Verify normalization/rewrite behavior; the durable fix is keeping secrets and backups outside the public origin.','2026-10-03 23:31:40','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(91,'Validate Rule Changes with Dry Run','Validate WAF and Rate Limiting rule changes before publishing them by appending dry_run=true to Rulesets API write requests.','General',12,13,'Recommended','Medium','Easy','API token with the same permission as the real change (for example, Zone > WAF > Edit).','curl --fail-with-body "https://api.cloudflare.com/client/v4/zones/$ZONE_ID/rulesets/$RULESET_ID/rules/$RULE_ID?dry_run=true" --request PATCH --header "Authorization: Bearer $CLOUDFLARE_API_TOKEN" --header "Content-Type: application/json" --data ''{"description":"Validate a scoped update","expression":"(http.host eq \"www.example.com\" and http.request.uri.path eq \"/.env\")","action":"block","enabled":true}''','https://developers.cloudflare.com/ruleset-engine/rulesets-api/dry-run/','Set IDs from the current configuration. Supported account/zone Rulesets mutation endpoints accept dry_run=true for POST/PUT/PATCH/DELETE and require the same authorization as the real write. Validation covers syntax, fields/functions, actions, phases, entitlements, quotas, and references. Normal 200 operations return result:null; normal 204 operations remain 204. This does not simulate traffic matches. PATCH a single rule; PUT of an entrypoint/ruleset replaces its rule list. Removing dry_run applies a real change, so review the identical payload first.','2026-10-03 23:31:40','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(92,'Roll Out New Blocking Rules Gradually','Apply a new mitigation to an approximate percentage of requests using hash_in_range() with cf.random_seed, then expand coverage while monitoring real traffic.','General',4,2,'Optional','Medium','Medium','Validated rule configuration and an observation/rollback plan; Log is Enterprise-only.','(http.host eq "www.example.com" and http.request.uri.path eq "/.env" and hash_in_range(0, 100, cf.random_seed) lt 10)','https://developers.cloudflare.com/changelog/post/2026-10-02-hash-in-range-ga/','Available for HTTP products on all plans since 2026-10-02. Bounds are integer literals: min inclusive, max exclusive. Raise the comparison threshold (10, 25, 50, 100), not the hash range. The hash algorithm may change without notice, so ip.src does not guarantee a permanently stable client cohort. SaaS custom metadata can control a per-hostname percentage: hash_in_range(0, 100, cf.random_seed) lt coalesce(lookup_json_integer(cf.hostname.metadata, "rollout_pct"), 0). Validate percentages in 0-100.','2026-10-03 23:31:40','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(93,'Rate Limit OTP, Verification and Password Reset Endpoints','Rate limit failed attempts on one-time password (OTP), email/SMS verification, and password reset endpoints, which are brute-forced like logins but frequently forgotten.','Security',5,3,'Recommended','High','Easy','Business or eligible Enterprise for response-code counting and the illustrated method-based match. Verify the requested counting period and mitigation timeout.','Match: (http.host eq "www.example.com" and http.request.uri.path in {"/api/otp/validate" "/account/verify" "/password-reset"} and http.request.method eq "POST"). API characteristics: ["ip.src", "cf.colo.id"]. Counting expression: (http.host eq "www.example.com" and http.request.uri.path in {"/api/otp/validate" "/account/verify" "/password-reset"} and http.request.method eq "POST" and http.response.code in {401 403}). Example threshold: 5 failures / 60 seconds; Block for 600 seconds, only if supported.','https://developers.cloudflare.com/waf/rate-limiting-rules/best-practices/#protect-otp-and-verification-endpoints','A custom counting expression replaces the default match expression, so repeat its scope. Response fields can bypass cache. After a failure threshold triggers, mitigation can also affect later valid submissions sharing that counter; do not promise zero impact. Tune against origin semantics and account/IP abuse, including SMS cost and recovery flows. If an Origin Rule rewrites Host, verify response-based counting still matches.','2026-10-03 23:31:40','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(94,'Rate Limit Clients Generating Errors','Mitigate clients generating many errors on selected browser navigation endpoints, using observed error rates and application behavior.','Security',5,3,'Situational','Medium','Medium','Business or eligible Enterprise for response-based counting. Bot Management is not required when using cf.client.bot.','Match: (http.host eq "www.example.com" and starts_with(http.request.uri.path, "/catalog/") and http.request.method eq "GET" and not cf.client.bot). API characteristics: ["ip.src", "cf.colo.id"]. Counting expression: (http.host eq "www.example.com" and starts_with(http.request.uri.path, "/catalog/") and http.request.method eq "GET" and not cf.client.bot and http.response.code in {403 404}). Example: 20 errors / 60 seconds. Managed Challenge only for browser navigations; use a non-interactive action for APIs.','https://developers.cloudflare.com/waf/rate-limiting-rules/best-practices/#limit-requests-from-bots','Repeat full scope when counting. Response fields can bypass cache. Broken links and SPAs can produce legitimate errors, so use a measured threshold. Narrow the operation rather than applying a host-wide error policy. Host rewrites in Origin Rules can prevent response-time counters from incrementing.','2026-10-03 23:31:40','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(95,'Rate Limit API Clients by Key or Token','For authenticated APIs, rate limit per API key, bearer token, or session instead of per IP, since one key may be used from many IPs and many keys from one IP.','Security',5,3,'Recommended','High','Medium','Enterprise Advanced Rate Limiting; API Shield JWT validation for the verified-claim example. Alternatively, a securely validated and stable API-key/session identifier.','Match: (http.host eq "api.example.com" and starts_with(http.request.uri.path, "/v1/") and any(cf.api_gateway.tokens.valid[*] eq "<TOKEN_CONFIGURATION_ID>")). Custom characteristic: lookup_json_string(http.request.jwt.claims["<TOKEN_CONFIGURATION_ID>"][0], "sub"); also include cf.colo.id. Require the selected subject claim and configure a separate IP-based rule for missing/invalid tokens.','https://developers.cloudflare.com/api-shield/security/jwt-validation/#rate-limit-by-jwt-claim','Raw header presence does not authenticate a client. Attacker-controlled or rotating keys/tokens can create fresh counters; a verified stable subject is preferable for per-user limits. Include the relevant issuer/tenant scope if subjects are not globally unique. Missing characteristics share a separate counter and empty values are distinct; define both behaviors. Application authorization remains required.','2026-10-03 23:31:40','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(96,'Rate Limit Content Scraping per Operation','Limit how often a client can perform a specific operation (for example, price lookups) to stop scraping by bots that evade other detections.','Security',5,3,'Situational','Medium','Easy','Business or eligible Enterprise for the illustrated 120/300-second counting periods; Free/Pro must use shorter supported periods and permitted fields.','Match: (http.host eq "www.example.com" and http.request.uri.path eq "/merchant" and http.request.uri.query contains "action=lookup_price"). API characteristics: ["ip.src", "cf.colo.id"]. Illustrative escalation: stricter Block rule (20 / 300 seconds) before browser Managed Challenge rule (10 / 120 seconds), if supported.','https://developers.cloudflare.com/waf/rate-limiting-rules/best-practices/#prevent-content-scraping-via-query-string','Use measured thresholds and supported periods. A terminating challenge before a stricter block can prevent that block from running/counting, so verify execution order instead of assuming escalation. Query substring matching is illustrative; use exact parsed values when your plan supports them. APIs require non-interactive controls.','2026-10-03 23:31:40','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(97,'Rate Limit GraphQL Operations','GraphQL APIs use a single path and mostly POST requests, so rate limit by operation name in the body (and, with API Shield, by query complexity) instead of by path and method.','Security',9,3,'Situational','Medium','Medium','Enterprise Advanced Rate Limiting and permitted request-body fields; GraphQL malicious query protection additionally requires API Shield.','Match: (http.host eq "api.example.com" and http.request.uri.path eq "/graphql" and http.request.method eq "POST" and http.request.body.raw contains "createReview"). API characteristics: ["ip.src", "cf.colo.id"], or a verified stable user/session identifier when configured. Set a measured rate/period and Block action.','https://developers.cloudflare.com/waf/rate-limiting-rules/best-practices/#protecting-graphql-apis','Raw substring matching is not a GraphQL parser and may match comments/variables or miss alternate queries and batching. GraphQL malicious query protection parses supported POST payloads on paths ending in /graphql, with a documented 20 KiB parsing limit; guard its fields with cf.api_gateway.graphql.parsed_successfully. Handle unparsed requests explicitly and distinguish individual query size/depth from complexity-based rate budgets.','2026-10-03 23:31:40','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(98,'Protect LLM Endpoints with AI Security for Apps','Detect and mitigate prompt injection, PII in prompts, and unsafe topics on LLM-powered endpoints (chatbots, assistants) with AI Security for Apps (formerly Firewall for AI).','Security',18,26,'Situational','High','Medium','Enterprise AI Security for Apps detection entitlement, WAF enabled, cf-llm labeled endpoints, JSON bodies, and detection enabled.','(http.host eq "api.example.com" and http.request.uri.path eq "/chat" and http.request.method eq "POST" and (cf.llm.prompt.injection_score lt 20 or cf.llm.prompt.pii_detected))','https://developers.cloudflare.com/waf/detections/ai-security-for-apps/','LLM endpoint discovery is available on all plans; detection fields and the AI Security Log Mode Ruleset are paid Enterprise capabilities. Observe detector quality before enforcing a policy; threshold 20 is illustrative and PII can be legitimate input. Do not use cf.llm.prompt.detected as a reason to block every prompt. Log Mode records full request bodies: review data handling before enabling it. Handle failed prompt detections explicitly.','2026-10-03 23:31:40','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(99,'Scan Uploads for Malicious Content','Use WAF content scanning to detect malware in uploaded files and block requests that contain malicious content objects.','Security',4,29,'Situational','High','Easy','Malicious uploads detection enabled (Enterprise add-on).','(http.host eq "www.example.com" and http.request.uri.path eq "/upload" and http.request.method in {"POST" "PUT" "PATCH"} and cf.waf.content_scan.has_malicious_obj)','https://developers.cloudflare.com/waf/detections/malicious-uploads/','Enable the detector first; its fields do not mitigate by themselves. Also observe has_failed, truncated, and cf.appsec.request.failed_detections containing waf_content_scan. Absence of a malicious result is not proof that a truncated/unscannable file is safe. Choose a separate rejection/quarantine policy for sensitive uploads and retain origin validation.','2026-10-03 23:31:40','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(100,'Use Threat Intelligence in WAF Rules','Match client IPs against Cloudforce One threat intelligence (IPs involved in DDoS or WAF attack activity in the past seven days) and combine it with other signals.','Security',4,28,'Situational','Medium','Easy','Active Cloudforce One subscription for cf.intel.ip fields; numeric WAF attack score entitlement and enabled detection for the example.','(any(cf.intel.ip.datasets[*] == "waf") and cf.waf.score lt 20)','https://developers.cloudflare.com/waf/detections/threat-intelligence/','Threat-intelligence values reflect recent IP activity and can aggregate different events; IPs may be shared. Observe and combine with endpoint-specific signals before blocking. Free investigation tools do not imply free access to cf.intel.ip rule fields. Treat detection failures separately; a missing score is not a clean request.','2026-10-03 23:31:40','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(101,'Control AI Crawlers by Purpose (Search, Agent, Training)','Use AI Crawl Control to decide separately whether AI search crawlers, AI agents, and AI training crawlers may access your content, and monitor robots.txt compliance.','General',6,27,'Recommended','Medium','Easy',NULL,'AI Crawl Control: set Search, Agent, and Training to allow, block on all pages, or block only on pages with ads. Optionally block individual crawlers and enforce robots.txt.','https://developers.cloudflare.com/ai-crawl-control/','AI Crawl Control is available on all plans; robots.txt and Content Signals express preferences rather than guaranteed enforcement. Avoid broad verified-bot Skip rules that undermine the intended policy. cf.bot_management.signed_agent is a Bot Management field identifying known Web Bot Auth agents, not a guarantee that every signed client is trusted or a feature entitlement granted by AI Crawl Control. Do not edit product-managed rules outside the owning workflow.','2026-10-03 23:31:40','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(102,'Enable Post-Quantum Encryption to the Origin','Make sure the origin server supports the hybrid post-quantum key agreement X25519MLKEM768 over TLS 1.3, so the Cloudflare-to-origin connection is protected against harvest-now, decrypt-later attacks.','Security',2,5,'Recommended','Medium','Medium','TLS 1.3 on the origin server.','bssl client -connect <YOUR_ORIGIN>:443 -curves X25519MLKEM768','https://developers.cloudflare.com/ssl/post-quantum-cryptography/pqc-to-origin/','Automatic key exchange (on by default) prefers X25519MLKEM768 whenever the origin supports it; only about 15% of origins did as of Birthday Week 2026. Verify that the handshake reports X25519MLKEM768. Monitor visitor-side adoption in HTTP Traffic Analytics or with the ClientTLSKeyExchangeGroup Logpush field.','2026-10-03 23:31:40','2026-10-03 23:31:40');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(103,'Enforce a Positive Security Model with Application Profiles','Let Cloudflare learn the expected structure of requests to your web application (data types, ranges, formats) and act on non-conforming requests with Security Rules.','Security',9,6,'Situational','High','Medium','Closed beta for invited Enterprise customers; customers with API Security already have access.','(http.host eq "api.example.com" and http.request.uri.path eq "/v1/orders" and http.request.method eq "POST" and cf.schema_validation.learned.violated)','https://developers.cloudflare.com/waf/detections/application-profiles/','Enable the selected operations, review Profile Analysis, then enforce narrowly with a custom rule; a learned profile is not automatic mitigation. Operations need 1,000 successful requests in seven days to learn fields and 10,000 to learn value boundaries. Profiles relearn weekly; review drift and pin an approved schema if needed. Multipart, GraphQL, and XML are unsupported; operations without a profile are not classified.','2026-10-03 23:31:40','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(104,'Handle Reported Security Detection Failures','Observe security detections that report a failure and decide explicitly whether sensitive operations reject, quarantine, or otherwise handle those requests.','Security',4,2,'Recommended','High','Medium','Available on all plans; the underlying detections and chosen rule action still require their own entitlement. Log requires Enterprise.','(http.host eq "www.example.com" and http.request.uri.path eq "/login" and http.request.method eq "POST" and any(cf.appsec.request.failed_detections[*] in {"waf_credential_check" "waf_score"}))','https://developers.cloudflare.com/ruleset-engine/rules-language/fields/reference/cf.appsec.request.failed_detections/','Introduced 2026-10-09. IDs report failures before custom-rule evaluation; [] means no failures were reported, not that all possible detections ran. Observe len(cf.appsec.request.failed_detections) gt 0 before deciding a scoped fail-closed policy. Other IDs cover content scanning, signatures, and AI prompt detections. The field itself neither enables detectors nor changes their behavior. A Request Header Transform Rule may forward join(cf.appsec.request.failed_detections, ",") to the origin.','2026-10-15 10:30:43','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(105,'Require Valid JWTs Before Trusting API Identity','Use verified token results to enforce authentication, and separately enforce expected claims and application authorization. Merely presenting a token or header is not authentication.','Security',9,6,'Recommended','High','Medium','API Shield JWT validation entitlement and a configured token source, keys, and token configuration.','(http.host eq "api.example.com" and starts_with(http.request.uri.path, "/v1/") and not any(cf.api_gateway.tokens.valid[*] eq "<TOKEN_CONFIGURATION_ID>"))','https://developers.cloudflare.com/api-shield/security/jwt-validation/#waf-custom-rule-examples','Action: Block after observation. Replace the configuration ID and exclude only legitimate token-issuance/refresh endpoints. WAF rules act when expressions are true; legacy API JWT validation rules act when their policy is false. is_jwt_valid() is not available in WAF custom rules. Validate expected issuer/audience and authorization requirements explicitly; rate-limit by a verified stable subject where supported.','2026-10-15 10:30:43','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(106,'Verify Origin TLS with Full (Strict)','Encrypt and authenticate the Cloudflare-to-origin connection with Full (strict), using an unexpired origin certificate that covers the hostname.','Security',2,5,'Recommended','High','Easy','Origin HTTPS listener with a valid matching public-CA or Cloudflare Origin CA certificate.','Set SSL/TLS encryption mode to Full (strict) after verifying every origin presents the correct certificate. Monitor certificate expiry and failures.','https://developers.cloudflare.com/ssl/origin-configuration/ssl-modes/full-strict/','Visitor/edge certificates do not replace origin certificates. Full without strict validation does not provide the same server identity verification. Combine strict server verification with origin access restrictions and, where needed, customer-specific Authenticated Origin Pulls.','2026-10-15 10:30:43','2026-10-15 10:30:43');
INSERT INTO "BestPractices" ("practice_id","title","description","domain","category_id","feature_id","recommendation_level","impact_level","difficulty_level","prerequisites","expressions_configuration_details","source_reference","notes","created_at","updated_at") VALUES(107,'Audit Security Bypasses and Narrow Managed Rule Exceptions','Review effective account/zone protection, IP Access Allow entries, Skip rules, and managed-rule exceptions so authenticated and sensitive operations are not silently exempted.','Security',4,2,'Recommended','High','Medium','Read access to account and zone security configuration; analytics for confirmed false positives.','Inventory IP Access rules and Skip rules, compare account/zone execute coverage, and scope managed-rule exceptions to the affected hostname, operation, and specific managed rule IDs.','https://developers.cloudflare.com/waf/feature-interoperability/','IP/ASN Allow entries can bypass custom rules, rate limiting, and managed rules and omit the requests from Security Events. Country Allow behaves differently. A Skip does not universally bypass every product; Bot Fight Mode cannot be skipped. Preserve authentication and schema validation. Confirm changes with dry run and traffic observation, and retain rollback versions.','2026-10-15 10:30:43','2026-10-15 10:30:43');
